const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg',asset=path=>new URL(path,import.meta.url).href;
const state={goldrush:{},dunerush:{}},history={goldrush:[],dunerush:[]};let data,mode='goldrush',brush=1,zoom=1,svg,selected=null,storage=true;const nodes=new Map(),viewport=$('map-viewport'),stage=$('map-stage');
const savedModes=new Set();try{for(const key of Object.keys(state)){const raw=localStorage.getItem('tatari-map:v1:'+(key==='goldrush'?'island-goldrush-default-homes':'dunerush-clam-tournament'));if(raw!==null){const saved=JSON.parse(raw);if(saved&&typeof saved==='object'&&!Array.isArray(saved)){state[key]=saved;savedModes.add(key);}}}}catch{storage=false;}
const make=(tag,attrs={})=>{const node=document.createElementNS(NS,tag);for(const [key,value] of Object.entries(attrs))node.setAttribute(key,String(value));return node;};
function map(){return data.maps[mode];}
