for(const b of document.querySelectorAll('[data-mode]')){b.onclick=()=>{if(!data||mode===b.dataset.mode)return;mode=b.dataset.mode;brush=Math.min(brush,map().teams.length-1);render();};b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const target=$(e.key==='Home'?'goldrush-tab':e.key==='End'?'dunerush-tab':mode==='goldrush'?'dunerush-tab':'goldrush-tab');target.click();target.focus();}};}
$('zoom-in').onclick=()=>setZoom(zoom+.5);$('zoom-out').onclick=()=>setZoom(zoom-.5);$('fit-map').onclick=()=>setZoom(1,false);
$('undo').onclick=()=>{const changes=history[mode].pop();if(!changes)return;for(const [id,previous] of changes){if(previous)state[mode][id]=previous;else delete state[mode][id];color(map().tiles.find(t=>t.id===id));}persist();$('tile-status').textContent='Last change undone.';};
$('clear-map').onclick=()=>{const changes=map().tiles.filter(t=>owner(t).id).map(t=>[t.id,owner(t).id,0]);if(!changes.length)return;history[mode].push(changes);state[mode]={};for(const t of map().tiles)color(t);persist();$('tile-status').textContent='Map cleared. Use Undo to restore it.';};
new ResizeObserver(()=>setZoom(zoom)).observe(viewport);
try{const response=await fetch(new URL('./map-layout.json?v=1',import.meta.url));if(!response.ok)throw Error('Map unavailable');data=await response.json();for(const [key,m] of Object.entries(data.maps))if(!savedModes.has(key))state[key]={...(m.defaultOwners||{}),...state[key]};render();}catch{$('map-summary').textContent='The map could not load. Please reload the page.';$('save-status').textContent='';}
